def main():
    raw = RM.read_bytes()
    if b"\r\n" in raw:
        raise SystemExit("REFUSED: the roadmap is LF and CRLF was found; nothing written")
    text = raw.decode("utf-8")
    if "\n**280. " in text or STATUS_267_NEW[:80] in text:
        raise SystemExit("REFUSED: already applied; nothing written")
    if text.count(HEADING_267) != 1:
        raise SystemExit("REFUSED: 267's heading is not there once; nothing written")
    h = text.find(HEADING_267)
    s = text.rindex("\n\n", 0, h) + 2
    if text[s:h] != STATUS_267_OLD:
        raise SystemExit("REFUSED: 267's status block is not the one this was written against; nothing written")
    text = text[:s] + STATUS_267_NEW + text[h:]
    if text.count(STATUS_267_NEW + HEADING_267) != 1:
        raise SystemExit("REFUSED: 267's status no longer adjoins its heading; nothing written")
    if text.count(BODY_267_LAST) != 1:
        raise SystemExit("REFUSED: 267's last paragraph is not there once; nothing written")
    b = text.index(BODY_267_LAST) + len(BODY_267_LAST)
    if text.find(HEADING_267) > b or text.find("\n\n**268. ", b) < 0:
        raise SystemExit("REFUSED: 267's last paragraph is not inside 267; nothing written")
    text = text[:b] + BODY_267_ADD + text[b:]
    heads = [int(m.group(1)) for m in re.finditer(r"(?m)^\*\*(\d+)\. ", text)]
    if max(heads) != 279 or heads[-1] != 279:
        raise SystemExit("REFUSED: the last item is not 279; nothing written")
    if not text.endswith("\n") or text.endswith("\n\n"):
        raise SystemExit("REFUSED: the roadmap does not end on one newline; nothing written")
    text = text + "\n" + ITEMS
    if len(re.findall(r"(?m)^\*STATUS: [^\n]*\*\n\n\*\*280\. ", text)) != 1:
        raise SystemExit("REFUSED: item 280's status does not adjoin its heading; nothing written")
    RM.write_bytes(text.encode("utf-8"))
    print("roadmap 267: NARROWED, the earlier status kept, a body paragraph added; item 280 appended; "
          "now roadmap_status.py --write / --check")
    return 0


if __name__ == "__main__":
    sys.exit(main())
